// Spike (d) probe: M4B chapter extraction. Throwaway.
//
// Question: can embedded chapter markers be read out of an M4B in pure Dart, with no platform
// plugin and no ffmpeg at runtime?
//
// Why pure Dart matters here: §2.4 puts this kind of logic in a pure-Dart package, and §1.5 lists
// "one large file with embedded chapter markers" as one of the four real-world layouts the
// Timeline has to represent. If chapter extraction needed a native dependency it would have to
// live behind a platform adapter and be implemented three times. It does not.
//
// The fixture is generated by fixtures/make.sh from a sine tone. No real audiobook is involved.
//
// Run: dart run bin/probe.dart fixtures/sample.m4b

import 'dart:io';
import 'dart:typed_data';

/// One chapter as stored in the file.
class Chapter {
  final Duration start;
  final String title;
  const Chapter(this.start, this.title);

  @override
  String toString() => '${_fmt(start)}  $title';
}

String _fmt(Duration d) {
  final h = d.inHours.toString().padLeft(2, '0');
  final m = (d.inMinutes % 60).toString().padLeft(2, '0');
  final s = (d.inSeconds % 60).toString().padLeft(2, '0');
  final ms = (d.inMilliseconds % 1000).toString().padLeft(3, '0');
  return '$h:$m:$s.$ms';
}

/// A minimal MP4 box walker. It only knows the containers it needs to descend through, which is
/// what keeps it small: everything else is skipped by its declared size.
class Mp4Reader {
  final Uint8List bytes;
  final ByteData _view;

  Mp4Reader(this.bytes) : _view = ByteData.sublistView(bytes);

  static const _containers = {
    'moov', 'udta', 'trak', 'mdia', 'minf', 'stbl', 'tref', 'edts',
  };

  /// Finds the first box of [type], descending only through known containers.
  /// Returns the offset of the box header, or -1.
  int findBox(String type, {int from = 0, int? to}) {
    final end = to ?? bytes.length;
    var off = from;
    while (off + 8 <= end) {
      final size = _view.getUint32(off);
      final name = String.fromCharCodes(bytes, off + 4, off + 8);
      final boxEnd = size == 0 ? end : off + size;
      if (size < 8 || boxEnd > end) return -1;
      if (name == type) return off;
      if (_containers.contains(name)) {
        final found = findBox(type, from: off + 8, to: boxEnd);
        if (found >= 0) return found;
      }
      off = boxEnd;
    }
    return -1;
  }

  /// Reads Nero-style chapters from `moov/udta/chpl`, if present.
  ///
  /// Layout, confirmed by hand against a generated file:
  ///   version(1) flags(3) reserved(4) count(1)
  ///   then per chapter: start(8, in 100-nanosecond units) titleLength(1) title(UTF-8)
  List<Chapter>? readChpl() {
    final off = findBox('chpl');
    if (off < 0) return null;
    final size = _view.getUint32(off);
    final end = off + size;
    var p = off + 8;
    final version = bytes[p];
    p += 4; // version + flags
    if (version == 1) p += 4; // reserved
    if (p >= end) return null;
    final count = bytes[p];
    p += 1;

    final out = <Chapter>[];
    for (var i = 0; i < count && p + 9 <= end; i++) {
      final ticks = _view.getUint64(p);
      p += 8;
      final len = bytes[p];
      p += 1;
      if (p + len > end) break;
      final title = String.fromCharCodes(bytes, p, p + len);
      p += len;
      // 100-nanosecond units: 10,000 per millisecond.
      out.add(Chapter(Duration(microseconds: ticks ~/ 10), title));
    }
    return out;
  }

  /// Reports whether the file also carries a QuickTime chapter track, which is the other way
  /// chapters are stored and the one Apple's own tools write.
  bool hasQuickTimeChapterTrack() => findBox('chap') >= 0;
}


/// A seek-based reader that never holds the file in memory.
///
/// This is the one that matters. §1.5 puts real M4B files at hundreds of megabytes to over a
/// gigabyte, and `readAsBytes` on a 1 GB book would be an out-of-memory crash on a phone. Box
/// headers are 8 bytes each, so walking the tree costs a few dozen small reads regardless of how
/// large the audio payload is.
class Mp4StreamReader {
  final RandomAccessFile _f;
  final int _length;
  int bytesRead = 0;

  Mp4StreamReader(this._f) : _length = _f.lengthSync();

  static const _containers = {
    'moov', 'udta', 'trak', 'mdia', 'minf', 'stbl', 'tref', 'edts',
  };

  Uint8List _readAt(int off, int n) {
    _f.setPositionSync(off);
    bytesRead += n;
    return _f.readSync(n);
  }

  int _findBox(String type, int from, int to) {
    var off = from;
    while (off + 8 <= to) {
      final head = _readAt(off, 8);
      final size = ByteData.sublistView(head).getUint32(0);
      final name = String.fromCharCodes(head, 4, 8);
      final boxEnd = size == 0 ? to : off + size;
      if (size < 8 || boxEnd > to) return -1;
      if (name == type) return off;
      if (_containers.contains(name)) {
        final found = _findBox(type, off + 8, boxEnd);
        if (found >= 0) return found;
      }
      off = boxEnd;
    }
    return -1;
  }

  List<Chapter>? readChpl() {
    final off = _findBox('chpl', 0, _length);
    if (off < 0) return null;
    final head = _readAt(off, 8);
    final size = ByteData.sublistView(head).getUint32(0);
    // The chapter list itself is small; reading it whole is fine.
    final body = _readAt(off + 8, size - 8);
    final view = ByteData.sublistView(body);
    var p = 0;
    final version = body[p];
    p += 4;
    if (version == 1) p += 4;
    if (p >= body.length) return null;
    final count = body[p];
    p += 1;
    final out = <Chapter>[];
    for (var i = 0; i < count && p + 9 <= body.length; i++) {
      final ticks = view.getUint64(p);
      p += 8;
      final len = body[p];
      p += 1;
      if (p + len > body.length) break;
      out.add(Chapter(
        Duration(microseconds: ticks ~/ 10),
        String.fromCharCodes(body, p, p + len),
      ));
      p += len;
    }
    return out;
  }
}

void main(List<String> args) {
  final path = args.isNotEmpty ? args.first : 'fixtures/sample.m4b';
  final file = File(path);
  if (!file.existsSync()) {
    stderr.writeln('missing fixture: $path (run fixtures/make.sh first)');
    exit(2);
  }

  final sw = Stopwatch()..start();
  final reader = Mp4Reader(file.readAsBytesSync());
  final chapters = reader.readChpl();
  sw.stop();

  stdout.writeln('--- spike (d): M4B chapter extraction in pure Dart ---');
  stdout.writeln('file: $path (${file.lengthSync()} bytes)');
  stdout.writeln('parsed in ${sw.elapsedMicroseconds}us');
  stdout.writeln('QuickTime chapter track present: ${reader.hasQuickTimeChapterTrack()}');
  stdout.writeln('');

  if (chapters == null) {
    stdout.writeln('no chpl atom found');
    exit(1);
  }

  stdout.writeln('chpl chapters: ${chapters.length}');
  for (final c in chapters) {
    stdout.writeln('  $c');
  }

  // The fixture is generated with these exact boundaries, so this is a real assertion.
  const expected = [
    (0, 'Chapter One'),
    (4000, 'Chapter Two'),
    (9000, 'Chapter Three'),
  ];
  var failures = 0;
  if (chapters.length != expected.length) {
    stdout.writeln('FAIL: expected ${expected.length} chapters, got ${chapters.length}');
    failures++;
  } else {
    for (var i = 0; i < expected.length; i++) {
      final (ms, title) = expected[i];
      final got = chapters[i];
      if (got.start.inMilliseconds != ms || got.title != title) {
        stdout.writeln('FAIL: chapter $i expected ${ms}ms "$title", '
            'got ${got.start.inMilliseconds}ms "${got.title}"');
        failures++;
      }
    }
  }

  // Now the same thing without loading the file, which is what production must do.
  final raf = file.openSync();
  final sw2 = Stopwatch()..start();
  final streamed = Mp4StreamReader(raf);
  final streamedChapters = streamed.readChpl();
  sw2.stop();
  raf.closeSync();

  stdout.writeln('');
  stdout.writeln('seek-based reader:');
  stdout.writeln('  parsed in ${sw2.elapsedMicroseconds}us');
  stdout.writeln('  bytes read: ${streamed.bytesRead} of ${file.lengthSync()} '
      '(${(streamed.bytesRead * 100 / file.lengthSync()).toStringAsFixed(2)}%)');
  final sameCount = streamedChapters?.length == chapters.length;
  final sameData = sameCount &&
      List.generate(chapters.length, (i) =>
          streamedChapters![i].title == chapters[i].title &&
          streamedChapters[i].start == chapters[i].start).every((x) => x);
  stdout.writeln('  identical to in-memory result: $sameData');
  if (!sameData) failures++;

  stdout.writeln('');
  stdout.writeln(failures == 0
      ? '--- all chapter boundaries and titles correct ---'
      : '--- $failures mismatches ---');
  exit(failures == 0 ? 0 : 1);
}
